    ["Turns off Override shared filters and caps for all units and reverts them to Shared."] = "Désactive les remplacements de filtres et limites pour toutes les unités et les réinitialise aux paramètres partagés.",
    ["Preview in Edit Mode"] = "Aperçu en mode édition",
    ["When enabled, placeholder auras can be shown while MSUF Edit Mode is active."] = "Si activé, des auras de remplacement sont affichées lorsque le mode édition MSUF est actif.",
