    ["Color aura timers by remaining time"] = "Colorer les compteurs d'aura selon le temps restant",
    ["When enabled, aura cooldown text uses Safe / Warning / Urgent colors based on remaining time.\nWhen disabled, aura cooldown text always uses the Safe color."] = "Si activé, le texte de recharge utilise les couleurs Sûr / Avertissement / Urgent selon le temps restant.\nSi désactivé, le texte utilise toujours la couleur Sûr.",
    ["Safe (seconds)"] = "Sûr (secondes)",
