    ["Party Interrupt Tracker"] = "Traqueur d'interruptions de groupe",
    ["Party Interrupt Tracker\n\nThis is a BEST-GUESS tracker:\n• Detects PARTY interrupts via UNIT_SPELLCAST_SUCCEEDED.\n• Cooldowns are estimated from a static table (talents/resets may differ).\n• Some abilities/modifiers cannot be inspected reliably in 12.0.\n\nIf other party members also use MSUF, kicks are synced via addon messages to improve reliability.\n\nMythic+ only (party). Disabled in raid/open world."] = "Traqueur d'interruptions de groupe\n\nCeci est un traqueur par estimation :\n• Détecte les interruptions de groupe via UNIT_SPELLCAST_SUCCEEDED.\n• Les recharges sont estimées depuis une table statique (les talents/réinitialisations peuvent différer).\n• Certaines capacités/modificateurs ne peuvent pas être inspectés de manière fiable en 12.0.\n\nSi d'autres membres du groupe utilisent MSUF, les interruptions sont synchronisées via les messages addon.\n\nMythique+ uniquement (groupe). Désactivé en raid/monde ouvert.",
    ["Enable party interrupt tracker"] = "Activer le traqueur d'interruptions de groupe",
    ["Show names"] = "Afficher les noms",
    ["WARNING: Best-guess tracking. Cooldowns are estimated; talents/resets may differ. If other party members use MSUF, kicks are synced via addon messages for better accuracy."] = "ATTENTION : Suivi par estimation. Les recharges sont estimées ; les talents/réinitialisations peuvent différer. Si d'autres membres utilisent MSUF, les interruptions sont synchronisées pour plus de précision.",
    ["Show READY"] = "Afficher PRÊT",
    ["Mythic+ only (party). Optional MSUF sync via addon messages. Disabled in raid/open world (0 overhead)."] = "Mythique+ uniquement (groupe). Synchronisation MSUF optionnelle via messages addon. Désactivé en raid/monde ouvert (0 surcharge).",
