    ["Disabling may require /reload to fully remove existing styling."] = "La désactivation peut nécessiter /reload pour supprimer complètement le style existant.",
    ["Rounded unitframes"] = "Cadres d'unité arrondis",
    ["Round MSUF unitframes by masking HP/Power/Absorb bars and backgrounds with the superellipse mask."] = "Arrondit les cadres MSUF en masquant les barres PV/Puissance/Absorption et les fonds avec un masque super-ellipse.",
