L["                   Confirm stages the reset; reload via /reload or MSUF Menu > Advanced > Factory Reset."] = "                   La confirmation prépare la réinitialisation ; rechargez avec /reload ou utilisez Menu MSUF > Avancé > Réinitialisation d'usine."
