L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "Ajout du cadre Cible de focalisation dans les réglages d'unité, le mode édition, les aperçus, les cibles de copie, les options de texte, les icônes et les rafraîchissements runtime."
