L["Edit Mode: |cff00ff00Active|r"] = "Mode d'édition : |cff00ff00Actif|r"
L["Editing %s"] = "Modification de %s"
L["Editing %s caps. Use Caps & Icons > Max Buffs = 0 to hide buffs only for this unit; Max Debuffs = 0 hides debuffs."] = "Modification des limites de %s. Utilisez Limites et icônes > Buffs max = 0 pour masquer les buffs seulement pour cette unité ; Débuffs max = 0 masque les débuffs."
L["Editing:"] = "Modification :"
L["EM_HELP_BTN"] = "? Aide"
L["EM_HELP_BTN_TIP"] = "Ouvre la configuration guidée complète de MSUF\nau chapitre du mode d’édition."
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r bascule l'ancre globale d'Essential Cooldown Manager. |cff60a5ffAnchor|r ouvre le sélecteur d'ancre ; survolez un cadre nommé, maintenez Ctrl et cliquez gauche pour l'utiliser comme ancre globale. Choisir une ancre personnalisée désactive CDM."
L["EM_HELP_COPYTO"] = "Dans les fenêtres d'unité et de barre d'incantation, |cff60a5ffCopy To|r copie les réglages de la fenêtre actuelle vers une autre cible. La copie de cadre d'unité conserve la position et les réglages d'ancre de la cible ; la copie de barre conserve les décalages X/Y de la cible."
L["EM_HELP_DRAG"] = "Maintenez le bouton gauche de la souris sur une superposition de déplaceur et faites-la glisser. Le cadre réel suit le déplaceur, et l'affichage X/Y sous la superposition indique le décalage actuel à l'écran. Relâchez pour valider la position."
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r quitte le mode d'édition et conserve les changements actuels. Entrer en combat quitte aussi le mode d'édition. Échap ferme ou annule une fenêtre ; le bouton Exit du HUD est la méthode normale pour quitter."
L["EM_HELP_NUDGE"] = "Les flèches déplacent la cible active. Priorité : poignée d'aperçu sélectionnée, fenêtre de barre d'incantation ouverte, fenêtre d'aura ouverte, puis cadre d'unité sélectionné. Pas : 1 px, Maj = 5 px, Ctrl = 10 px, Alt = pas actuel de la grille."
L["EM_HELP_OPACITY"] = "Faites défiler le contrôle |cff60a5ffBG ##%|r pour changer uniquement l'opacité du fond du mode d'édition. Cela ne change ni l'alpha des cadres d'unité ni leur visibilité enregistrée."
L["EM_HELP_POPUP"] = "Un clic gauche sur un déplaceur sans glisser ouvre sa fenêtre d'édition. Les fenêtres d'unité modifient taille, position, ancres de texte, réglages de puissance détachée et options de copie vers une unité. Les déplaceurs de barres et d'auras ouvrent leurs propres fenêtres ciblées."
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r affiche des données factices pour cible, focalisation, cible de la cible, familier, boss et aperçus de barres absents pendant que le mode d'édition est actif. |cff60a5ffAuras|r bascule les icônes d'aperçu d'aura et les boîtes de déplacement d'auras."
L["EM_HELP_SNAP"] = "La grille est une aide visuelle. Clic gauche sur |cff60a5ffGrid ##px|r active ou désactive les lignes ; la molette change l'espacement. |cff60a5ffSnap|r est séparé : activé, les déplaceurs glissés s'alignent sur le centre de l'écran ou les bords/centres des autres déplaceurs visibles, avec des guides orange."
L["EM_HELP_TITLE"] = "Mode d'édition - Référence rapide"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r et |cff60a5ffRedo|r restaurent les changements récents du mode d'édition capturés avant les glissements, déplacements aux flèches et modifications de fenêtres. |cff60a5ffCancel All|r demande confirmation, restaure l'instantané d'avant l'entrée en mode d'édition, puis quitte."
