L["This group scope uses custom font settings. Shared name-shortening changes will not affect it until the override is reset."] = "Cette portée de groupe utilise une police personnalisée. Les changements de raccourcissement partagé ne l'affecteront qu'après réinitialisation du remplacement."
L["This preview layer follows Blizzard/native placement and is locked."] = "Cette couche d'aperçu suit le placement natif de Blizzard et est verrouillée."
L["This scope follows Shared bar settings. Turn on custom settings here only when this scope needs different bars."] = "Cette portée suit les réglages de barres partagés. Activez les réglages personnalisés ici seulement si cette portée a besoin de barres différentes."
L["This scope follows Shared font settings. Turn on custom settings here only when this scope needs different fonts."] = "Cette portée suit les réglages de police partagés. Activez les réglages personnalisés ici seulement si elle a besoin de polices différentes."
L["This scope follows Shared name shortening. Turn on custom settings above only when this scope needs different names."] = "Cette portée suit le raccourcissement partagé. Activez les réglages personnalisés ci-dessus seulement si elle a besoin de noms différents."
L["This scope is using custom bar settings. Shared changes will not affect it until the override is reset."] = "Cette portée utilise des réglages de barre personnalisés. Les changements partagés ne l'affecteront qu'après réinitialisation du remplacement."
L["This scope is using custom font settings. Shared changes will not affect it until the override is reset."] = "Cette portée utilise des réglages de police personnalisés. Les changements partagés ne l'affecteront qu'après réinitialisation du remplacement."
L["This scope uses custom font settings. Shared name-shortening changes will not affect it until the override is reset."] = "Cette portée utilise une police personnalisée. Les changements de raccourcissement partagé ne l'affecteront qu'après réinitialisation du remplacement."
L["This unit follows Shared aura settings. Enable custom filters, caps, or layout only when this unit needs different auras."] = "Cette unité suit les réglages d'aura partagés. Activez filtres, limites ou disposition personnalisés seulement si elle a besoin d'auras différentes."
L["This unit uses custom aura settings."] = "Cette unité utilise des réglages d'aura personnalisés."
L["Tip: Gameplay colors are in Colors > Gameplay"] = "Astuce : les couleurs de gameplay sont dans Couleurs > Gameplay"
