L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Highlights keep Blizzard icons while allowing MSUF's dispel border, glow, and overlay visuals."] = "Le mode Blizzard laisse WoW placer les types d'aura sélectionnés. Le mode MSUF personnalisé permet à MSUF de contrôler taille, croissance, position, filtres et style. Les surbrillances de dissipation MSUF gardent les icônes Blizzard tout en laissant MSUF afficher la bordure, la lueur et l'overlay de dissipation."
L["Blizzard renderer is still active, but this group is MSUF Custom because its Use Blizzard toggle is off. Other active Blizzard aura types can still show matching spells, so duplicates can appear."] = "Le moteur de rendu Blizzard reste actif, mais ce groupe est en MSUF Custom car son interrupteur Utiliser Blizzard est desactive. D'autres types d'aura Blizzard actifs peuvent encore afficher les sorts correspondants, donc des doublons peuvent apparaitre."
