L["Checked categories hide MSUF custom debuff icons only. Blizzard-rendered debuffs bypass this list while Use Blizzard: Debuffs is enabled."] = "Les categories cochees masquent uniquement les icones d'affaiblissement personnalisees de MSUF. Les affaiblissements affiches par Blizzard ignorent cette liste tant que Utiliser Blizzard : Affaiblissements est active."
