L["When enabled, WoW owns buff icons. MSUF hide categories and custom buff positioning do not filter Blizzard-rendered buffs, so Skyfury or Earth Shield can still appear."] = "Quand cette option est activee, WoW gere les icones d'amelioration. Les categories masquees de MSUF et le positionnement personnalise des ameliorations ne filtrent pas les ameliorations affichees par Blizzard, donc Skyfury ou Earth Shield peuvent encore apparaitre."
