L["Profile-wide · follows the active Party, Raid, or Mythic Raid frame appearance"] = "Pour tout le profil · reprend l’apparence des cadres actifs de groupe, raid ou raid mythique"
L["Keep tanks and manually pinned group members in one stable strip without removing them from the normal Party or Raid frames."] = "Gardez les tanks et les membres épinglés manuellement dans une bande stable sans les retirer des cadres normaux de groupe ou de raid."
L["Profile-wide layout · character-specific pins · available in parties and raids · inherits the active group-frame appearance and click-cast behavior."] = "Disposition pour tout le profil · épinglages propres au personnage · disponible en groupe et en raid · reprend l’apparence et les sorts au clic des cadres de groupe actifs."
L["Waiting — enable Party frames first."] = "En attente — activez d’abord les cadres de groupe."
L["Waiting — none of your saved players are in the current group."] = "En attente — aucun joueur enregistré ne se trouve dans le groupe actuel."
L["Ready — pin a group member or include tanks automatically."] = "Prêt — épinglez un membre du groupe ou incluez automatiquement les tanks."
L["Ready — join a party or raid to show Priority Frames."] = "Prêt — rejoignez un groupe ou un raid pour afficher les cadres prioritaires."
L["Hover an MSUF Party, Raid, or Priority frame and press this key to pin or unpin that player."] = "Survolez un cadre MSUF de groupe, raid ou prioritaire et appuyez sur cette touche pour épingler ou libérer ce joueur."
L["No manual pins yet. While grouped, hover an MSUF Party, Raid, or Priority frame, then press your hotkey."] = "Aucun épinglage manuel. En groupe, survolez un cadre MSUF de groupe, raid ou prioritaire, puis appuyez sur votre raccourci."
L["Use the hover hotkey above to add or remove players."] = "Utilisez le raccourci de survol ci-dessus pour ajouter ou retirer des joueurs."
L["Saved · not grouped"] = "Enregistré · hors groupe"
