L["Saved · Party frames disabled"] = "Enregistré · cadres de groupe désactivés"
L["Attach the strip to the active Party, Raid, or Mythic Raid container, or choose Free position and place it with Edit Mode."] = "Attachez la bande au conteneur actif de groupe, raid ou raid mythique, ou choisissez Position libre et placez-la avec le mode Édition."
L["Right of group frames"] = "À droite des cadres de groupe"
L["Left of group frames"] = "À gauche des cadres de groupe"
L["Above group frames"] = "Au-dessus des cadres de groupe"
L["Below group frames"] = "Sous les cadres de groupe"
L["The strip follows the active Party, Raid, or Mythic Raid container automatically."] = "La bande suit automatiquement le conteneur actif de groupe, raid ou raid mythique."
L["In party"] = "En groupe"
L["In raid"] = "En raid"
L["Not grouped"] = "Hors groupe"
L["Priority Frames keep automatic tanks and manually pinned group members in a stable extra strip. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. The matching base group frames must be enabled. Open Group Frames > Priority to choose who appears, set a hover hotkey, and place the strip."] = "Les cadres prioritaires conservent les tanks automatiques et les membres épinglés dans une bande supplémentaire stable. En groupe, ils héritent des cadres de groupe ; en raid, des cadres actifs de raid ou raid mythique. Les cadres de base correspondants doivent être activés. Ouvrez Cadres de groupe > Priorité pour choisir les membres, le raccourci et la position."
L["Free position uses the dedicated Priority Frames mover."] = "La position libre utilise le déplaceur dédié aux cadres prioritaires."
L["How do Priority Frames work?"] = "Comment fonctionnent les cadres prioritaires ?"
L["Opens: Group Frames > Priority"] = "Ouvre : Cadres de groupe > Priorité"
L["Pin or unpin hovered group member"] = "Épingler ou libérer le membre survolé"
L["Priority Frames hotkey"] = "Raccourci des cadres prioritaires"
L["Left-click and press a key. Right-click, Backspace, or Delete clears it. Existing bindings are never replaced without confirmation."] = "Faites un clic gauche et appuyez sur une touche. Un clic droit, Retour arrière ou Suppr. l’efface. Une assignation existante n’est jamais remplacée sans confirmation."
