L["Health and Power use separate gradient colors. Choosing a color creates a custom Bars override for the selected scope."] = "La santé et le pouvoir utilisent des couleurs dégradées distinctes. Le choix d'une couleur crée un remplacement de barres personnalisé pour la portée sélectionnée."
L["UPGRADED TO MSUF %s"] = "MISE À NIVEAU VERS MSUF %s"
L["Your MSUF 6.0 highlights"] = "Vos points forts MSUF 6.0"
L["Your current profile stays unchanged. Review %d new highlights and choose only what you want to configure."] = "Votre profil actuel reste inchangé. Passez en revue les nouveaux points forts du %d et choisissez uniquement ce que vous souhaitez configurer."
L["CURRENT PROFILE: %s - NO SETTINGS WILL BE CHANGED"] = "PROFIL ACTUEL : %s - AUCUN PARAMÈTRE NE SERA MODIFIÉ"
L["Start %d-highlight tour"] = "Démarrer la visite guidée du %d"
L["Review the release highlights without changing your current profile."] = "Consultez les points forts de la version sans modifier votre profil actuel."
L["Review exactly what you would skip before closing the tour."] = "Passez en revue exactement ce que vous sauteriez avant de terminer la visite."
L["About two minutes. You can leave at any point and configure each area later."] = "Environ deux minutes. Vous pouvez partir à tout moment et configurer chaque zone plus tard."
L["Highlight %d of %d"] = "Mettez en surbrillance %d de %d"
L["WHY IT MATTERS"] = "POURQUOI C'EST IMPORTANT"
L["Finish tour"] = "Terminer la visite"
L["Next highlight"] = "Point culminant suivant"
L["Mark this highlight as reviewed and continue."] = "Marquez ce point culminant comme révisé et continuez."
L["Back"] = "Dos"
L["Skip tour"] = "Passer la visite"
L["See the remaining highlights before deciding to skip them."] = "Consultez les faits saillants restants avant de décider de les ignorer."
L["Skip %d remaining highlights?"] = "Ignorer les faits saillants restants de %d ?"
L["Your profile will stay safe, but you will leave these %d new configuration areas unexplored:"] = "Votre profil restera en sécurité, mais vous laisserez ces nouvelles zones de configuration %d inexplorées :"
L["Show me the highlights"] = "Montre-moi les points forts"
L["Skip all %d and continue"] = "Ignorer tous les %d et continuer"
L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "Sauter clôture uniquement cette tournée de versions. Chaque paramètre reste disponible dans Menu2."
L["Custom Aura tracking on Unitframes"] = "Suivi Aura personnalisé sur Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "Créez jusqu'à trois couloirs personnalisés sur Joueur, Cible, Focus et Boss, ajoutez des SpellID exacts de buffs ou débuffs, et suivez vos propres DoTs sur la Cible via un couloir par classe."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "Vos images MSUF peuvent agir comme des trackers ciblés de style WeakAura avec des icônes, des minuteries, des barres de durée et des effets de teinte, de bordure, de lueur ou d'impulsion plein format."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "trois trackers Aura personnalisés par Unitframe pris en charge, listes blanches de sorts exactes et effets plein format"
L["Build a Custom tracker"] = "Créer un tracker personnalisé"
L["Aura settings in the right place"] = "Les réglages d'aura au bon endroit"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "La configuration et le style individuel se trouvent maintenant dans les menus correspondants des cadres d'unité et de groupe/raid. Apparence > Auras contient les styles partagés étendus."
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "Configurez chaque cadre dans son contexte, puis utilisez Auras pour partager les formes d'icône, les bordures, les ombres, les couleurs et l'espacement."
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "les contrôles d'aura par cadre et le style partagé étendu dans Apparence > Auras"
L["Open shared Aura styles"] = "Ouvrir les styles d'aura partagés"
L["Adaptive Party and Raid layouts"] = "Dispositions adaptatives de groupe et de raid"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "Groupe, Raid et Raid mythique gagnent des dispositions adaptatives avec mise à l'échelle, des filtres et listes noires d'auras par couloir, une page Dispel Overlay dédiée - et vous choisissez par type de groupe si MSUF ou Blizzard dessine les cadres."
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "Une seule configuration de groupe peut vous suivre d'un donjon à cinq jusqu'au raid, et vous décidez ligne par ligne quelles auras ont le droit d'apparaître."
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "les dispositions adaptatives, les filtres et listes noires d'auras de groupe, la page Dispel Overlay et le choix du fournisseur par groupe"
L["Open Group Layout"] = "Disposition du groupe ouvert"
L["New health values and text formats"] = "Nouvelles valeurs de santé et formats de texte"
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "Le texte de vie peut afficher des valeurs abrégées ou complètes avec un formatage plus cohérent, et le nouvel overlay de vie maximale perdue marque la vie maximale réduite sur les cadres d'unité et de groupe."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Vous pouvez choisir une lisibilité compacte ou des nombres exacts sans renoncer à la mise en page que vous utilisez déjà."
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "les nouvelles abréviations de vie, valeurs complètes, formats de texte et l'overlay de vie maximale perdue"
L["Open HP Text Editor"] = "Ouvrir l'éditeur de texte de vie"
L["More flexible class resources"] = "Des ressources de classe plus flexibles"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Les ressources de classe ont bénéficié de mises en page détachées, de formes supplémentaires et de couleurs plus fines par emplacement et par état complet."
L["You can move class information where your eyes already are and make important states easier to read."] = "Vous pouvez déplacer les informations de classe là où se trouvent déjà vos yeux et rendre les états importants plus faciles à lire."
L["detached class resources, new shapes and per-state colors"] = "ressources de classe détachées, nouvelles formes et couleurs par état"
L["Configure Class Resources"] = "Configurer les ressources de classe"
L["Cast target text"] = "Caster le texte cible"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "Les barres de lancement de cible, de concentration et de boss peuvent désormais indiquer qui est ciblé par le sort actuel, avec un style de texte dédié."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Vous pouvez identifier la destination d'une distribution importante sans détourner votre attention de la barre de distribution."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "noms des cibles de diffusion et leur style de texte sur les cadres Target, Focus et Boss"
L["Open Target Cast Bar"] = "Ouvrir la barre de diffusion cible"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "Consultez ou ignorez les points forts de la version sur le tableau de bord avant d'utiliser les actions de premier chargement."
L["Priority Frames for the units that matter"] = "Cadres prioritaires pour les unités qui comptent"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "Épinglez jusqu'à cinq membres du groupe à la main, ou laissez MSUF choisir les tanks automatiquement, et donnez-leur leur propre bande qui ne se réorganise jamais en plein combat."
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "Les personnes que vous devez surveiller gardent une place fixe à l'écran, avec l'apparence de groupe ou de raid et le clic-incantation qu'elles avaient déjà."
L["Priority Frames, manual and automatic pinning, and their own placement"] = "les cadres prioritaires, l'épinglage manuel et automatique et leur propre placement"
L["Set up Priority Frames"] = "Configurer les cadres prioritaires"
L["One Colors page with click-to-paint"] = "Une page Couleurs avec peinture au clic"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "Toutes les couleurs ont été regroupées sur une seule page, en espaces de travail Joueur & Cible, Groupe & Raid, Barre d'incantation, Auras, Ressource et Ressource de classe, chacun avec son aperçu en direct."
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "Vous cliquez sur l'élément dans l'aperçu pour le peindre au lieu de chercher la bonne pastille, et vous réutilisez n'importe quelle couleur d'une palette récente ou enregistrée."
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "la page Couleurs reconstruite, les aperçus à peindre au clic, les palettes et le nouveau sélecteur de couleur"
L["Open the Colors page"] = "Ouvrir la page Couleurs"
L["One 0-30 layer scale for everything"] = "Une seule échelle de calques 0-30 pour tout"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "Textes, icônes d'état, auras, bordures, contours de barre, indicateurs de groupe et ressources de classe s'ordonnent tous sur une même échelle de calques 0-30."
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "Vous décidez exactement de ce qui s'affiche devant quoi, et l'aperçu des calques à côté de n'importe quel curseur de calque montre toute la pile d'un coup."
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "l'échelle de calques 0-30 valable pour tout l'addon et l'aperçu des calques"
L["MSUF Edit Mode, rebuilt"] = "Le mode Édition de MSUF, reconstruit"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "Le mode Édition a gagné une barre d'outils ancrable, des menus rapides redessinés sur chaque cadre, et Annuler et Rétablir qui s'y comportent comme dans le menu."
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "Vous déplacez, redimensionnez et copiez les cadres directement à l'écran et revenez sur n'importe quelle erreur sans rouvrir le menu."
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "la nouvelle barre d'outils du mode Édition, ses menus rapides et le Annuler/Rétablir partagé"
L["Start Edit Mode"] = "Démarrer le mode Édition"
L["Spell Indicators on Group Frames"] = "Spell Indicators sur les cadres de groupe"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "Suivez des buffs choisis sur les cadres de groupe et de raid en icône, carré, barre ou nombre, avec listes de sorts personnalisées et indicateurs d'angle."
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "Vous voyez les externals manquants ou expirant et les buffs clés directement sur les cadres, avec lueur d'expiration, surbrillance de la barre de vie et effets sur tout le cadre."
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "les Spell Indicators avec listes d'auras personnalisées, indicateurs d'angle et alertes d'expiration"
L["Open Spell Indicators"] = "Ouvrir les Spell Indicators"
L["Fill Direction for Health and Power"] = "Sens de remplissage Vie et Ressource"
L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "Chaque cadre d'unité peut remplir sa Vie et sa Ressource de gauche à droite, droite à gauche, bas en haut ou haut en bas."
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "Les dispositions verticales ou en miroir deviennent un choix par cadre - ce qu'aucun autre addon d'unit frames ne propose actuellement."
L["the per-frame Fill Direction control for Health and Power bars"] = "le sens de remplissage par cadre pour les barres de Vie et de Ressource"
L["Choose a Fill Direction"] = "Choisir un sens de remplissage"
L["Portraits: attached, detached or overlay"] = "Portraits : attaché, détaché ou overlay"
L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "Les portraits restent attachés, flottent librement ou s'affichent en overlay dans la barre de vie - avec taille indépendante, ancrage en neuf points, opacité et zoom déplaçable."
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "Les portraits rectangulaires ou en filigrane deviennent possibles, et les anneaux Relief plus les bordures épousant la forme encadrent les portraits carrés, ronds, arrondis et diamant."
L["the new portrait placement modes, Relief rings and shape-following portrait borders"] = "les nouveaux placements de portrait, les anneaux Relief et les bordures épousant la forme"
L["Open Portrait settings"] = "Ouvrir les réglages de portrait"
L["Status icon packs"] = "Packs d'icônes de statut"
L["Role, leader, raid marker, ready check and every other status icon can switch between twelve bundled styles or your own custom icons, per indicator."] = "Rôle, chef, marqueur de raid, test de préparation et chaque autre icône de statut peuvent basculer entre douze styles fournis ou vos propres icônes, par indicateur."
L["Status icons can finally match your UI style instead of always using Blizzard art, and external packs can register through SharedMedia."] = "Les icônes de statut peuvent enfin suivre le style de votre interface au lieu de l'art Blizzard, et des packs externes peuvent s'enregistrer via SharedMedia."
L["the twelve status icon styles and per-indicator custom icons"] = "les douze styles d'icônes de statut et les icônes personnalisées par indicateur"
L["Pick an icon style"] = "Choisir un style d'icônes"
