L["Raid focus: compare Raid and Mythic scopes before reviewing each highlighted section."] = "Focus Raid : comparez les portées Raid et Mythic avant de revoir chaque section en surbrillance."
L["Solo focus: keep group defaults or prepare the Party scope for occasional groups."] = "Focus solo : conservez les paramètres de groupe par défaut ou préparez le périmètre Party pour des groupes occasionnels."
L["Dungeon focus: begin with Party or Mythic scope, then review each highlighted section."] = "Focus sur le donjon : commencez par la portée Party ou Mythic, puis passez en revue chaque section en surbrillance."
L["Compare the Party, Raid or Mythic scope that matters to you, then follow the highlights."] = "Comparez la portée Party, Raid ou Mythic qui vous intéresse, puis suivez les faits saillants."
L["Sample = visual only · tests = temporary · scope = shared/unit/group"] = "Échantillon = visuel uniquement · tests = temporaire · portée = partagée/unit/group"
