L["Spell-specific channel tick markers"] = "Marqueurs de graduation de canal spécifiques au sort"
L["Runs a short castbar for the global cooldown whenever an instant spell triggers it.\n\nThe fill and time text are driven natively by the client from the real (haste-scaled) GCD duration - no per-frame addon work while the bar runs. A real cast, channel or empower always takes priority."] = "Affiche une courte barre d'incantation pour le temps de recharge global lorsqu'un sort instantané le déclenche.\n\nLe remplissage et le texte de temps sont pilotés nativement par le client à partir de la durée réelle du GCD (ajustée par la hâte) - aucun travail de l'addon par image pendant que la barre est active. Une incantation réelle, une canalisation ou un sort amplifié est toujours prioritaire."
L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "Affiche les séparateurs de ticks sur la barre de diffusion du joueur pendant la canalisation.\n\nLes sorts pris en charge utilisent leur nombre de ticks réel, y compris les changements de talents et de durée de canal pris en charge. Les canaux non pris en charge conservent cinq lignes de secours régulièrement espacées. Les paramètres de graduation de canal personnalisés remplacent la disposition automatique.\n\nLes marqueurs sont pilotés par les événements et n'ajoutent aucune interrogation de canal récurrente."
L["Class Color (Reaction fallback)"] = "Couleur de classe (réaction de repli)"
L["Ready color (kick available)"] = "Couleur prête (kick disponible)"
L["Not ready color (kick on cooldown)"] = "Couleur non prête (lancement du temps de recharge)"
L["PvP Flag (War Mode/PvP)"] = "Drapeau PvP (Mode Guerre/PvP)"
L["Abbreviate HP values (K/M)"] = "Valeurs HP abrégées (K/M)"
L["For specializations that use mana alongside another resource."] = "Pour les spécialisations qui utilisent le mana avec une autre ressource."
L["Smooths resource changes. Runes, Essence recharge, and timers keep their own animation."] = "Lisse les changements de ressources. Les runes, la recharge d'essence et les minuteries conservent leur propre animation."
L["Exact Spell IDs are used when Blizzard exposes them."] = "Les identifiants de sort exacts sont utilisés lorsque Blizzard les expose."
L["Reverses only the swipe overlay. Icon size and position stay unchanged."] = "Inverse uniquement la superposition de balayage. La taille et la position de l’icône restent inchangées."
L["Only relevant sorting methods are shown for buffs and debuffs."] = "Seules les méthodes de tri pertinentes sont affichées pour les buffs et les debuffs."
L["Reversed flips the complete priority order."] = "Inversé inverse l’ordre de priorité complet."
L["Choose which auras Blizzard provides for this lane."] = "Choisissez les auras que Blizzard fournit pour cette voie."
