L["Normal"] = "Normale"
L["On previews every enabled spell of every tracked spec, including spells that only draw a frame effect. Off previews only the selected spell."] = "Activé prévisualise chaque sort activé de toutes les spécialisations suivies, y compris les sorts qui ne dessinent qu'un effet de cadre. Désactivé affiche uniquement le sort sélectionné."
L["Opacity remains beside the setting when that element supports it."] = "L'opacité reste à côté du paramètre lorsque cet élément le prend en charge."
L["Open Aura Style"] = "Style d'aura ouverte"
L["Open Bars"] = "Barres ouvertes"
L["Open Colors > Bar Gradient Colors for separate Health and Power gradient colors in the selected Bars scope."] = "Ouvrez Couleurs > Couleurs de dégradé de barre pour des couleurs de dégradé de santé et de puissance distinctes dans la portée des barres sélectionnées."
L["Open Colors > Group Frame Colors for shared Party, Raid and Mythic Raid colors."] = "Ouvrez Couleurs > Couleurs de cadre de groupe pour les couleurs partagées de Party, Raid et Mythic Raid."
L["Open Edit Mode and move Party Frames"] = "Ouvrez le mode édition et déplacez les cadres de fête"
L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Ouvrez Cadres de groupe > Auras pour les filtres Buff/Debuff, les listes, la visibilité et la mise en page. Pour le texte, les temps de recharge, les cumuls et les barres de durée, utilisez Apparence > Auras et sélectionnez la portée Groupe ou Raid."
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "Ouvrez Cadres de groupe > Mise en page. Le texte, la barre de ressources et le fondu de plage sont disposés à côté des principes de base du cadre et de la transparence. Dispel Overlay et Debuff Stripe se trouvent sur la page Dispel Overlay. La prédiction de guérison se trouve dans Style global > Barres > Affichage d'absorption."
L["Open it and choose a different value."] = "Ouvrez-le et choisissez une valeur différente."
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "Ouvrez le UnitFrame > Auras > Debuffs concerné et activez la règle Dispellable native. Pour les groupes/raids, utilisez Cadres de groupe > Auras > Debuffs."
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "Ouvrez le UnitFrame > Auras > Debuffs concerné et utilisez sa liste noire SpellID spécifique au cadre. Les exclusions de groupe se trouvent directement dans Cadres de groupe > Auras > Debuffs."
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "Ouvrez le UnitFrame > Auras concerné et choisissez Buffs ou Debuffs. Vérifiez ses filtres Blizzard spécifiques au cadre, sa liste noire, son état activé et sa casquette d'icône. Pour les groupes/raids, utilisez Cadres de groupe > Auras."
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "Ouvrez le UnitFrame > Auras concerné pour la visibilité, la mise en page, les filtres et les listes noires. Utilisez Apparence > Auras pour le temps de recharge, la pile, la barre de durée et le style des icônes en fonction de la portée."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "Ouvrez le cadre et développez Auras. Les buffs et debuffs contiennent leurs propres filtres et listes noires Blizzard ; Custom 1-3 contient sa propre liste blanche. Il n’y a pas d’onglet Filtre séparé."
L["Open the matching color section below."] = "Ouvrez la section des couleurs correspondantes ci-dessous."
L["Opens Buff styling for this frame. Spell choice, placement, size, layer, and frame highlight stay unique to this indicator."] = "Ouvre le style Buff pour ce cadre. Le choix des sorts, l’emplacement, la taille, le calque et la surbrillance du cadre restent uniques à cet indicateur."
