L["Type a new value, then press Enter."] = "Tapez une nouvelle valeur, puis appuyez sur Entrée."
L["UNLOCK, THEN CHANGE IT - Enable Corner Indicators, choose a slot, then select Custom Spell when requested."] = "DÉVERROUILLEZ, PUIS CHANGEZ-LE - Activez les indicateurs de coin, choisissez un emplacement, puis sélectionnez Sort personnalisé lorsque cela est demandé."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spec, then press a tracked spell tile."] = "DÉBLOQUEZ, PUIS CHANGEZ-LE - Activez les indicateurs de sort, choisissez une spécification, puis appuyez sur une tuile de sort suivi."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then select a Frame Effect."] = "DÉBLOQUEZ, PUIS CHANGEZ-LE - Activez les indicateurs de sort, choisissez un sort, puis sélectionnez un effet de cadre."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then set Indicator Type."] = "DÉVERROUILLEZ, PUIS CHANGEZ-LE - Activez les indicateurs de sort, choisissez un sort, puis définissez le type d'indicateur."
L["UNLOCK, THEN CHANGE IT - Enable the parent feature in this section first."] = "DÉVERROUILLER, PUIS LE MODIFIER - Activez d'abord la fonctionnalité parent dans cette section."
L["UNLOCK, THEN CHANGE IT - Turn on Spell Indicators in the earlier checkpoint; use Back if you skipped it."] = "DÉVERROUILLEZ, PUIS CHANGEZ-LE - Activez les indicateurs de sort au point de contrôle précédent ; utilisez Retour si vous l'avez ignoré."
L["Unit frame status icons are on each unit page. Group Spell Indicators are in Group Frames > Auras; group status and corner indicators are in Group Frames > Status & Indicators."] = "Les icônes d’état du cadre d’unité se trouvent sur chaque page d’unité. Les indicateurs de sort de groupe se trouvent dans Cadres de groupe > Auras ; l'état du groupe et les indicateurs de coin se trouvent dans Cadres de groupe > État et indicateurs."
