-- MSUF FULL CORE MENU SOURCE INVENTORY 2
-- Generated missing non-Assistant core keys for frFR.
L["+"] = "+"
L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "Les cadres prioritaires peuvent-ils sélectionner automatiquement les guérisseurs, les DPS, les classes ou les spécialisations ?"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "Les cadres prioritaires peuvent-ils afficher automatiquement les évocateurs d'augmentation ?"
L["Can Priority Frames show my co-tank?"] = "Les cadres prioritaires peuvent-ils afficher mon co-tank ?"
L["Can Priority Frames update during combat?"] = "Les cadres prioritaires peuvent-ils être mis à jour pendant le combat ?"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "Vérifiez que les cadres prioritaires sont activés, que vous êtes groupé et que les cadres de base Party ou Raid correspondants sont activés. Confirmez qu'un tank assigné ou un joueur épinglé manuellement est actuellement dans le groupe et que les emplacements visibles ne sont pas pleins. Les joueurs absents enregistrés ne créent aucun espace réservé vide et les modifications de liste protégées apportées au combat se terminent après la fin du combat."
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "La couleur de classe et le dégradé de santé sont des couleurs d'exécution, et non un seul échantillon modifiable."
L["Cleave Training Dummy"] = "Mannequin d'entraînement Cleave"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "Les personnalisations 1 à 3 sont toujours stockées par image. Le style des icônes et les effets plein format changent ici uniquement"
L["Disabled or whitelist empty"] = "Désactivé ou liste blanche vide"
L["Do Priority Frame pins persist, and what order do they use?"] = "Les épingles du cadre prioritaire persistent-elles et dans quel ordre sont-elles utilisées ?"
L["Do Priority Frames inherit click casting and appearance?"] = "Les cadres prioritaires héritent-ils de la diffusion des clics et de l'apparence ?"
L["Do Priority Frames use polling?"] = "Les cadres prioritaires utilisent-ils le sondage ?"
L["Do Priority Frames work in parties and dungeons?"] = "Les cadres prioritaires fonctionnent-ils dans les groupes et les donjons ?"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "Les cadres prioritaires existants restent utilisables en combat, mais WoW protège l'adhésion sécurisée aux cadres de groupe et les modifications de disposition. Tout changement de broche, de liste, d'emplacement ou de placement nécessitant une actualisation sécurisée est appliqué après la fin du combat. Modifiez la combinaison de touches des images prioritaires hors combat."
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "Suit la coloration globale Unitframe. L'échantillon affiche un aperçu de la couleur actuelle de la barre globale."
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "Pour les cadres prioritaires, la disposition s'étend à l'échelle du profil, tandis que les épingles sont spécifiques aux caractères. Les emplacements visibles peuvent être définis entre un et cinq. Les réservoirs automatiques se remplissent en premier, suivis par les broches manuelles dans l'ordre enregistré ; les sélections en double apparaissent une fois. Un joueur sauvegardé qui est absent attend qu'il rejoigne le groupe actuel."
L["How do I pin or unpin a player in Priority Frames?"] = "Comment puis-je épingler ou désépingler un joueur dans les cadres prioritaires ?"
L["How do I position Priority Frames?"] = "Comment positionner les cadres prioritaires ?"
L["How should an Augmentation Evoker use Priority Frames?"] = "Comment un évocateur d’augmentation doit-il utiliser les cadres prioritaires ?"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "Hérité : cette portée suit le style d'aura partagée. Activez le style d'aura personnalisé uniquement lorsque cette étendue nécessite des paramètres de texte, de balayage, de bordure ou de minuterie différents."
L["Live "] = "En direct"
L["Live preview is unavailable for this container. Sample mode remains available."] = "L'aperçu en direct n'est pas disponible pour ce conteneur. Le mode échantillon reste disponible."
L["Live preview updates after combat. Sample mode remains available."] = "Mises à jour d'aperçu en direct après le combat. Le mode échantillon reste disponible."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "Épinglez manuellement les coéquipiers que vous souhaitez garder visibles pour la surveillance ou la diffusion par clic. Priority Frames ne décide pas qui doit recevoir Prescience ou Ebon Might. Configurez Cadres de groupe > Auras > Indicateurs de sort si vous souhaitez que les cadres de priorité hérités affichent Prescience, Ebon Might, Shifting Sands, Blistering Scales ou d'autres effets configurés."
L["Native · "] = "Autochtone ·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "Aucun ticker d'interrogation continue ni boucle OnUpdate n'est utilisé pour la sélection de priorité. Il résout la liste lorsque la configuration, les broches, l'état du groupe ou les modifications pertinentes de l'identité de l'unité nécessitent une actualisation. La sélection automatique lit le rôle TANK attribué à WoW et n'inspecte pas la spécialisation de chaque membre du groupe en arrière-plan."
L["No live "] = "Pas de direct"
L["No live member"] = "Aucun membre vivant"
L["No matching aura active"] = "Aucune aura correspondante active"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "Non. La sélection automatique utilise actuellement uniquement le rôle TANK attribué à WoW. Les guérisseurs, DPS, classes, spécialisations et cibles de support doivent être épinglés manuellement avec le raccourci clavier. Cela évite l’inspection ou l’interrogation des antécédents et maintient la sélection déterministe."
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "Ouvrez Cadres de groupe > Priorité > Placement. Attachez la bande à droite, à gauche, en haut ou en bas du conteneur Party/Raid actif, ou choisissez la position Libre et utilisez le déménageur d'images prioritaires dédié en mode édition. La même page contrôle la croissance, l'espacement, l'espacement des pièces jointes et le décalage d'alignement."
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "Override actif : cette lunette conserve son propre style d'aura. Les modifications de style partagées ne le remplaceront pas tant que le remplacement n'aura pas été réinitialisé."
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "Priority Frames ne détecte pas automatiquement les spécialisations des autres joueurs. La sélection automatique ne prend actuellement en charge que les chars attribués à WoW. Épinglez un Evoker d'augmentation manuellement avec le raccourci clavier ; Priority Frames ne choisit pas les cibles idéales de Prescience ou d'Ebon Might."
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "Les cadres prioritaires dupliquent les chars automatiques et épinglent manuellement les membres actuels du groupe dans une bande supplémentaire stable sans les supprimer des cadres normaux de groupe ou de raid. Dans un groupe, ils héritent des Party Frames ; dans un raid, ils héritent des cadres actifs Raid ou Mythic Raid. Ils fonctionnent dans les groupes, les raids et les raids mythiques, héritent du comportement de clic-cast des cadres de groupe actifs et nécessitent que les cadres de groupe de base correspondants soient activés."
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "Le style d’aura partagé constitue la référence pour les paramètres de texte, de balayage, de bordure et de minuterie d’aura d’image unitaire. Party et Raid sont des étendues de style groupe avec leurs propres paramètres."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "Les textures sont partagées, à l'exception des remplacements de cadres de groupe Party/Raid. Les dégradés peuvent être personnalisés par unité ou par groupe."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "Cette portée de groupe peut utiliser des textures et des dégradés personnalisés. Le Raid s'applique également au Raid Mythique."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "Cette portée peut utiliser des dégradés et des paramètres de barre personnalisés. Les textures suivent toujours Partagé."
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "Cette étendue suit les paramètres de la barre partagée. Activez les paramètres personnalisés ici lorsque cette étendue nécessite différents dégradés ou paramètres de barre."
L["Updates after combat"] = "Mises à jour après le combat"
L["Where can I request a Priority Frames feature?"] = "Où puis-je demander une fonctionnalité de cadres prioritaires ?"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "Une fois groupé, définissez le raccourci clavier sur Group Frames > Priority. Survolez une image MSUF Party, Raid ou Prioritaire et appuyez sur la touche de raccourci Images prioritaires pour épingler ou désépingler ce joueur. Les joueurs ne peuvent pas être ajoutés en tapant un nom ou en dehors du groupe actuel ; une épingle absente enregistrée attend et réapparaît lorsque ce joueur rejoint."
L["Why are my Priority Frames empty or missing?"] = "Pourquoi mes cadres prioritaires sont-ils vides ou manquants ?"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "Oui. Inclure les tanks sélectionne automatiquement les membres actuels du groupe dont le rôle attribué par WoW est TANK, comprenant normalement vous et votre co-tank. Pour afficher uniquement votre co-tank, désactivez les réservoirs automatiques et épinglez manuellement l'autre réservoir. Si WoW n'a pas attribué à ce joueur le rôle TANK, l'épinglage manuel est la solution de secours."
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "Oui. Les cadres prioritaires héritent de l'apparence du cadre actif Party, Raid ou Mythic Raid, y compris les barres configurées, le texte, les auras, les indicateurs de statut et les indicateurs de sort. Ils utilisent le même comportement d'enregistrement et d'unité de diffusion par clic MSUF, de sorte que les liaisons de diffusion par clic existantes fonctionnent également sur les images dupliquées."
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "Oui. Les cadres prioritaires fonctionnent dans les groupes, les raids et les raids mythiques. Dans un groupe ou un donjon, ils héritent des cadres de groupe ; dans un raid, ils héritent de la configuration active Raid ou Mythic Raid. Ils ne créent pas de bande solo et les images de base Party ou Raid correspondantes doivent être activées."
