L["Right-click to follow the shared castbar text color again."] = "Clic droit pour suivre à nouveau la couleur de texte partagée de la barre d'incantation."
L["Color for the selected text indicator. Right-click to follow the frame font color again."] = "Couleur de l'indicateur de texte sélectionné. Clic droit pour suivre à nouveau la couleur de police du cadre."
L["Castbar text follows the shared Fonts settings until this text gets its own color."] = "Le texte de la barre d'incantation suit les réglages de police partagés jusqu'à ce qu'il ait sa propre couleur."
L["Font style follows the Fonts menu for this frame; the color can be set per indicator."] = "Le style de police suit le menu Polices de ce cadre ; la couleur se règle par indicateur."
L["Each castbar text can override the shared castbar text color. Target text exists on Target and Focus only."] = "Chaque texte de barre d'incantation peut remplacer la couleur partagée. Le texte de cible n'existe que sur Cible et Focalisation."
L["Color for a single text indicator on one frame. Unset indicators follow that frame's font color."] = "Couleur d'un seul indicateur de texte sur un cadre. Sans couleur définie, l'indicateur suit la police du cadre."
L["Aura Style > Defensive Buffs can follow the frame portrait shape."] = "Style d'aura > Buffs défensifs peut suivre la forme du portrait du cadre."
L["Cooldown timer urgency plus shared icon border and shadow colors."] = "Urgence du minuteur de temps de recharge, plus les couleurs partagées de bordure et d'ombre d'icône."
