--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "Toujours masqué"
L["Blizzard Raid Manager"] = "Gestionnaire de raid Blizzard"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "L'onglet de Blizzard sur le bord gauche de l'écran, avec vérification de préparation, symboles de raid et filtres de rôle. C'est un cadre unique partagé, donc ce réglage est le même pour Groupe, Raid et Raid mythique."
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "Estompe le gestionnaire de raid jusqu'à ce que la souris le touche. La vérification de préparation, les symboles de raid et les filtres de rôle restent accessibles, et un panneau déplié reste visible jusqu'à ce que vous le repliiez."
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "Garde le gestionnaire de raid invisible et transparent aux clics en permanence. Rebasculez le réglage pour accéder à ses boutons."
L["Show on mouseover"] = "Afficher au survol"
L["Automatic"] = "Automatique"
L["Always visible"] = "Toujours visible"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "Masque le gestionnaire de raid tant que MSUF fournit les cadres de groupe actifs, et le laisse à WoW sinon. C'est ainsi que MSUF s'est toujours comporté."
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "Garde le gestionnaire de raid accessible même avec les cadres de groupe MSUF activés. Utilisez ceci si vous voulez conserver sa vérification de préparation, ses symboles de raid et ses filtres de rôle."
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "Partagé par Groupe, Raid et Raid mythique. Automatique garde l'onglet masqué tant que MSUF fournit les cadres de groupe."
L["MSUF detected %s."] = "MSUF detected %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."
L["Second confirmation for %s."] = "Second confirmation for %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirm only if you want the whole Unit Frame layout to move with your cooldowns."
L["Confirm anchoring"] = "Confirm anchoring"
L["Continue"] = "Continue"
L["Keep independent"] = "Keep independent"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "%s détecté : l’ancre globale suit le gestionnaire des temps de recharge essentiels. Désactivez-la avec Cooldown dans le mode édition de MSUF."
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "%s détecté : l’ancrage au gestionnaire des temps de recharge est désactivé. Activez-le avec Cooldown dans le mode édition de MSUF."
L["Cooldown Manager anchoring (%s)"] = "Ancrage au gestionnaire des temps de recharge (%s)"
L["Global anchor (%s Anchor)"] = "Ancrage global (ancrage %s)"
L["Fades all four outer edges; 0% keeps the original texture."] = "Estompe les quatre bords extérieurs ; 0 % conserve la texture d'origine."

-- Menu localization pass 2026-08-06: previously untranslated menu strings.
L["1:1 shows the configured aura pixel size."] = "1:1 affiche la taille d'aura en pixels configurée."
L["Aura Options"] = "Options d'aura"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "Les Options d'aura et le Style d'aura appartiennent à ce UnitFrame. Apparence globale des icônes : Apparence > Style d'aura."
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "En dessous de cette valeur, le temps restant peut afficher une décimale. Utilisez 0 pour n'afficher que des secondes entières."
L["Buff Appearance"] = "Apparence des buffs"
L["Debuff Appearance"] = "Apparence des affaiblissements"
L["Global Aura Appearance: Buffs"] = "Apparence globale des auras : Améliorations"
L["Global Aura Appearance: Debuffs"] = "Apparence globale des auras : Affaiblissements"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "Les couleurs du minuteur sont partagées par les auras d'unité/groupe en direct et tous les aperçus. Les couleurs de bordure et d'ombre des icônes se trouvent dans Apparence > Auras et sont définies par type d'aura."
L["Click to open the setting that enables this layer."] = "Cliquez pour ouvrir le réglage qui active ce calque."
L["Controls native Aura tooltips for Spell Icons only."] = "Contrôle les info-bulles d'aura natives uniquement pour les Icônes de sorts."
L["Cooldown text format"] = "Format du texte de temps de recharge"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "Copie la présentation des buffs, débuffs, défensifs externes et Icônes de sorts, y compris le zoom d'icône, le texte, le balayage, les barres de durée et le tri. Les Options d'aura, les Icônes de sorts suivies et le thème global d'Apparence restent inchangés."
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "Copie la visibilité, la disposition, les filtres, les listes noires exactes et par catégorie, le niveau d'affichage et les options de dissipation des auras de groupe. Le Style d'aura et le thème global d'Apparence restent inchangés."
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "Copie la visibilité des auras, la disposition, les filtres, les listes noires, la configuration des auras personnalisées et les sorts suivis de ce UnitFrame. Le Style d'aura et le thème global d'Apparence restent inchangés."
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "Copie la présentation des buffs, débuffs, auras personnalisées, défensifs du joueur et DoTs sur la cible de ce UnitFrame, y compris le texte, le balayage, le zoom d'icône, les barres de durée, la pandémie et les effets plein cadre. Les Options d'aura et le thème global d'Apparence restent inchangés."
L["Drag background (%dx)"] = "Faire glisser l'arrière-plan (%dx)"
L["Drag to move. Arrow keys nudge."] = "Faites glisser pour déplacer. Les touches fléchées ajustent finement."
L["EllesmereUI"] = "EllesmereUI"
L["EllesmereUI Unlock Mode"] = "Mode déverrouillage EllesmereUI"
L["Exact X coordinate"] = "Coordonnée X exacte"
L["Exact Y coordinate"] = "Coordonnée Y exacte"
L["Fit shows the complete aura layout."] = "Ajuster affiche la disposition d'aura complète."
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "Thème global d'Apparence sélectionné uniquement par type d'aura. La disposition, les filtres, les minuteurs, le texte et les effets restent liés à leur portée dans le UnitFrame ou le GroupFrame correspondant."
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "Le Style individuel se modifie ici. Thème d'icônes partagé : Apparence > Style d'aura."
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "La disposition, les filtres, les listes et chaque Style propre à un conteneur résident dans chaque cadre. Apparence > Style d'aura ne gère que le thème global d'icônes."
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "Mesuré depuis le centre du cadre prévisualisé. Les valeurs positives déplacent vers la droite. Les touches fléchées et le glisser mettent à jour la même position."
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "Mesuré depuis le centre du cadre prévisualisé. Les valeurs positives déplacent vers le haut. Les touches fléchées et le glisser mettent à jour la même position."
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "Activé (par défaut) : les cadres MSUF apparaissent dans le Mode déverrouillage EllesmereUI. Désactivez-le pour continuer à utiliser le Mode édition natif de MSUF. Les positions du profil MSUF restent la référence."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "Ouvrez le cadre et développez Auras. Les buffs et les débuffs disposent de leur propre disposition, de leurs filtres, listes noires et Style ; Personnalisée 1-3, Buffs défensifs et DoTs sur la cible proposent les réglages adaptés à leur contenu."
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "Ouvre le thème global d'icônes d'aura : bordure, ombre, couleurs, marge de rangée et enchantements d'arme natifs du joueur. Le Style individuel de ce GroupFrame reste ici."
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "AVERTISSEMENT DE PERFORMANCES (12.1) : Blizzard peut exécuter un OnUpdate à chaque image sur chaque bouton d'aura visible tant que l'aura possède une fenêtre de pandémie calculée, et pas seulement pendant l'affichage de l'alerte. N'activez ceci que si vous acceptez ce coût potentiellement élevé en combat."
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Applique une teinte de substitution sur les GroupFrames actifs afin de juger la superposition sans véritable débuff dissipable. Se désactive de lui-même à la fermeture de cette page."
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Applique une teinte de substitution sur le UnitFrame actif afin de juger la superposition sans véritable débuff dissipable. Se désactive de lui-même à la fermeture de cette page."
L["Position is controlled by the colored aura handle in Preview."] = "La position se règle avec la poignée d'aura colorée dans l'Aperçu."
L["Preview position"] = "Position de l'aperçu"
L["Runtime Preview"] = "Aperçu en conditions réelles"
L["Runtime Preview: live GroupFrames"] = "Aperçu en conditions réelles : GroupFrames actifs"
L["Runtime Preview: live UnitFrame"] = "Aperçu en conditions réelles : UnitFrame actif"
L["Runtime Preview: live UnitFrame (drag)"] = "Aperçu en conditions réelles : UnitFrame actif (glisser)"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "Forme, bordure et ombre : Apparence > Style d'aura > Buffs. Tous les réglages présents ici restent liés à la portée de groupe."
L["Shared Aura Style"] = "Style d'aura partagé"
L["Shared Aura Style: Buffs"] = "Style d'aura partagé : buffs"
L["Shared Aura Style: Debuffs"] = "Style d'aura partagé : débuffs"
L["Shared Preview - "] = "Aperçu partagé - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "Affiche des symboles de substitution sur le UnitFrame actif et vous laisse les glisser en position sans véritable débuff. Se désactive de lui-même à la fermeture de cette page."
L["Spell Icon Style"] = "Style des Icônes de sorts"
L["Spell Icon tooltip"] = "Info-bulle des Icônes de sorts"
L["Swipe Direction"] = "Sens du balayage"
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "Ce commutateur n'apparaît que lorsque EllesmereUI est chargé. Le désactiver ramène immédiatement MSUF à son propre Mode édition."
L["Use - / + or Ctrl + mouse wheel to zoom."] = "Utilisez - / + ou Ctrl + molette de la souris pour zoomer."
L["Use EllesmereUI Unlock Mode for MSUF"] = "Utiliser le Mode déverrouillage EllesmereUI pour MSUF"
L["Use the colored Texture handle in Preview for exact placement."] = "Utilisez la poignée de texture colorée dans l'Aperçu pour un placement précis."
L["Zoom changes only this preview, not your Aura settings."] = "Le zoom ne modifie que cet aperçu, pas vos réglages d'aura."

