L["Grid2 Edit Mode integration"] = "Intégration de Grid2 au Mode édition"
L["On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."] = "Activé (par défaut) : le Mode édition MSUF peut déplacer chaque fenêtre Details! active. Les fenêtres accolées par Details! se déplacent comme un seul groupe natif."
L["On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."] = "Activé (par défaut) : le Mode édition MSUF peut déplacer la disposition de Grid2 et ses groupes détachés actifs. Grid2 reste propriétaire de sa disposition et de ses positions enregistrées."
