-- Menu localization pass 2026-08-06 (part 7): entries that were still identity English.
L["Confirm anchoring"] = "Confirmer l'ancrage"
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Ne confirmez que si vous voulez que toute la disposition du cadre d'unité se déplace avec vos temps de recharge."
L["Keep independent"] = "Garder indépendant"
L["MSUF detected %s."] = "MSUF a détecté %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF va maintenant ancrer la disposition globale du cadre d'unité à Essential Cooldown Manager."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Rien ne bougera tant que vous n'aurez pas confirmé à l'étape suivante. Si vous choisissez Garder indépendant, vous pourrez activer l'ancrage CDM à tout moment dans le Mode édition MSUF ou sous Unité > Ancrage dans le menu MSUF."
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Rien ne bougera tant que vous n'aurez pas confirmé à l'étape suivante. Vous pourrez changer cela plus tard dans le Mode édition MSUF."
L["Second confirmation for %s."] = "Seconde confirmation pour %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Voulez-vous que MSUF ancre la disposition globale du cadre d'unité à Essential Cooldown Manager ?"
L["MISSION %d/%d - %d XP"] = "MISSION %d/%d - %d XP"
L["Perf..."] = "Perf..."
L["Portrait Y"] = "Portrait Y"
L["Section %d / %d · Action %d / %d · %s"] = "Section %d / %d · Action %d / %d · %s"
L["Section %d / %d · Option %d / %d · %s"] = "Section %d / %d · Option %d / %d · %s"
-- Menu localization pass 2026-08-06 (part 7): native Player resource pings.
L["Enable native Player resource pings (12.1)"] = "Activer les pings natifs de ressource du joueur (12.1)"
L["Native Player resource pings"] = "Pings natifs de ressource du joueur"
L["Contextual pings over the MSUF Player frame can call out health and, when Blizzard supports it, mana. Blizzard does not expose separate Health/Power selection or Energy, Rage and Focus pings. The portrait keeps the normal Player unit ping and radial wheel."] = "Les pings contextuels sur le cadre Joueur de MSUF peuvent signaler la santé et, lorsque Blizzard le permet, le mana. Blizzard n’expose ni sélection distincte Santé/Ressource, ni pings d’énergie, de rage ou de focalisation. Sur le portrait, le ping d’unité Joueur normal et la roue radiale restent disponibles."
L["Edits the selected element's X position. Positive values move right. Arrow keys and dragging update the same position."] = "Modifie la position X de l'élément sélectionné. Les valeurs positives le déplacent vers la droite. Les flèches et le glissement actualisent la même position."
L["Edits the selected element's Y position. Positive values move up. Arrow keys and dragging update the same position."] = "Modifie la position Y de l'élément sélectionné. Les valeurs positives le déplacent vers le haut. Les flèches et le glissement actualisent la même position."
L["Exact X position"] = "Position X exacte"
L["Exact Y position"] = "Position Y exacte"
L["External frame"] = "Cadre externe"
L["Next page"] = "Page suivante"
L["Previous page"] = "Page précédente"

L["UnitFrame Debuff blacklist"] = "Liste noire des affaiblissements des UnitFrames"
L["You can blacklist any debuff applied by the player on the %s UnitFrame using its exact Spell ID. The debuff on the unit can carry a different Spell ID than the spell you cast - use the ID from the debuff itself."] = "Vous pouvez placer sur liste noire tout affaiblissement appliqué par le joueur sur l’UnitFrame %s via son ID de sort exact. L’affaiblissement sur l’unité peut porter un ID de sort différent de celui du sort lancé - utilisez l’ID de l’affaiblissement lui-même."
L["Spell ID vs. aura ID"] = "ID de sort vs ID d’aura"
L["The aura on the unit can use a different Spell ID than the spell you cast. Enter the ID shown on the aura itself. After adding, MSUF checks the live unit and warns when only a same-named aura with a different ID is active."] = "L’aura sur l’unité peut utiliser un ID de sort différent de celui du sort lancé. Saisissez l’ID affiché par l’aura elle-même. Après l’ajout, MSUF vérifie l’unité et avertit si seule une aura du même nom avec un autre ID est active."
L["%s (#%d) is active on this frame right now - blacklist entry verified."] = "%s (#%d) est actuellement actif sur ce cadre - entrée de la liste noire vérifiée."
L["#%d is not active on this frame, but %s is currently active as #%d. The aura's ID can differ from your cast's Spell ID."] = "#%d n’est pas actif sur ce cadre, mais %s est actuellement actif sous #%d. L’ID de l’aura peut différer de l’ID du sort lancé."
L["Block #%d instead"] = "Bloquer #%d à la place"
L["Active auras on this frame"] = "Auras actives sur ce cadre"
L["Shows the result of the last scan: every readable aura with the exact ID it carried, plus everything captured earlier this session. Press Rescan to scan the current unit - blocking from this list always uses the aura's own ID. Secret auras cannot be listed."] = "Affiche le résultat de la dernière analyse : chaque aura lisible avec son ID exact, plus tout ce qui a été capturé durant cette session. Cliquez sur Réanalyser pour analyser l’unité actuelle - bloquer depuis cette liste utilise toujours l’ID de l’aura elle-même. Les auras secrètes ne peuvent pas être listées."
L["No scan yet - click Rescan"] = "Aucune analyse pour le moment - cliquez sur Réanalyser"
L["Start combat scan"] = "Démarrer l’analyse en combat"
L["Closes the menu and keeps scanning this frame's auras until combat ends or you press Stop. Every aura an addon can block is captured with its icon - auras Blizzard keeps secret cannot be blocked by any addon."] = "Ferme le menu et continue d’analyser les auras de ce cadre jusqu’à la fin du combat ou jusqu’à ce que vous appuyiez sur Arrêter. Chaque aura qu’un addon peut bloquer est capturée avec son icône - les auras gardées secrètes par Blizzard ne peuvent être bloquées par aucun addon."
L["Scanning auras - creating a list"] = "Analyse des auras - création d’une liste"
L["%d captured so far"] = "%d capturées pour l’instant"
L["%d captured so far - %d hidden by Blizzard"] = "%d capturées pour l’instant - %d masquées par Blizzard"
L["Hidden auras are Blizzard-secret - no addon can block them. Everything blockable was captured."] = "Les auras masquées sont des secrets Blizzard - aucun addon ne peut les bloquer. Tout ce qui peut être bloqué a été capturé."
L["Blocked by Blizzard during this fight - resumes automatically. In instances, use the curated presets."] = "Bloqué par Blizzard pendant ce combat - reprend automatiquement. En instance, utilisez les ensembles prédéfinis."
L["Blizzard is blocking aura scanning right now (encounter, Mythic+, or PvP match). Use the curated presets - they cover everything blockable in instanced content."] = "Blizzard bloque l’analyse des auras en ce moment (rencontre, Mythique+ ou match JcJ). Utilisez les ensembles prédéfinis - ils couvrent tout ce qui peut être bloqué en instance."
L["Scan complete: %d auras readable right now, %d captured this session. %d more are hidden by Blizzard and cannot be blocked by any addon."] = "Analyse terminée : %d auras lisibles actuellement, %d capturées dans cette session. %d autres sont masquées par Blizzard - aucun addon ne peut les bloquer."
L["Stop scan"] = "Arrêter"
L["Block selected aura"] = "Bloquer l’aura sélectionnée"
L["Blocks the selected aura using the exact ID it carries right now."] = "Bloque l’aura sélectionnée en utilisant l’ID exact qu’elle porte actuellement."
L["No readable auras right now"] = "Aucune aura lisible pour le moment"
L["Rescan"] = "Réanalyser"
L["Re-reads the auras on the current unit and adds everything it sees to this session's captured list - works in combat too. Shift-click clears the captured list."] = "Relit les auras de l’unité actuelle et ajoute tout ce qui est vu à la liste capturée de cette session - fonctionne aussi en combat. Maj + clic vide la liste capturée."
L["%s - captured"] = "%s - capturée"
L["Scan complete: %d auras readable right now, %d captured this session."] = "Analyse terminée : %d auras lisibles actuellement, %d capturées dans cette session."

-- Finalisation de la localisation complète issue de Menu2.
L["Aura settings are only available for Player, Target, Focus, and Boss Frames."] = "Les réglages des auras ne sont disponibles que pour les cadres Joueur, Cible, Focalisation et Boss."
L["Aura settings were skipped for unsupported UnitFrames."] = "Les réglages des auras ont été ignorés pour les cadres d’unité non pris en charge."
L["Blizzard animated Zzz"] = "Zzz animés de Blizzard"
L["Bottom half"] = "Moitié inférieure"
L["Castbar settings are only available for Player, Target, Focus, and Boss Frames."] = "Les réglages de la barre d’incantation ne sont disponibles que pour les cadres Joueur, Cible, Focalisation et Boss."
L["Castbar settings were skipped for UnitFrames without Castbars."] = "Les réglages de la barre d’incantation ont été ignorés pour les cadres d’unité sans barre d’incantation."
L["Changing this value selects Manual width. For Player, it also turns off Sync width to Class Resource so the new width takes effect immediately."] = "La modification de cette valeur sélectionne Largeur manuelle. Pour le Joueur, elle désactive aussi Synchroniser la largeur avec la ressource de classe afin que la nouvelle largeur soit appliquée immédiatement."
L["Current target only"] = "Cible actuelle uniquement"
L["Edits the selected child element's local X offset. Positive values move right. Arrow keys and dragging update the same offset."] = "Modifie le décalage X local de l’élément enfant sélectionné. Les valeurs positives le déplacent vers la droite. Les touches fléchées et le glissement mettent à jour le même décalage."
L["Edits the selected child element's local Y offset. Positive values move up. Arrow keys and dragging update the same offset."] = "Modifie le décalage Y local de l’élément enfant sélectionné. Les valeurs positives le déplacent vers le haut. Les touches fléchées et le glissement mettent à jour le même décalage."
L["Exact X offset"] = "Décalage X exact"
L["Exact Y offset"] = "Décalage Y exact"
L["Full texture"] = "Texture complète"
L["Height (0 = auto)"] = "Hauteur (0 = auto)"
L["Highlight texture"] = "Texture de surbrillance"
L["No copy categories selected."] = "Aucune catégorie de copie sélectionnée."
L["Nothing was copied."] = "Rien n’a été copié."
L["Outline style"] = "Style du contour"
L["Rounded frames ignore True Outline and Texture styles and keep the solid outline color."] = "Les cadres arrondis ignorent les styles Contour réel et Texture et conservent la couleur unie du contour."
L["Texture region"] = "Région de la texture"
L["Top half"] = "Moitié supérieure"
L["True Outline"] = "Contour réel"
L["offset, size, and layer"] = "décalage, taille et calque"

L["Requires a UI reload."] = "Nécessite un rechargement de l'interface."
L["Shared entries apply to every spec."] = "Les entrées partagées s'appliquent à toutes les spécialisations."
L["down"] = "bas"
L["left"] = "gauche"
L["No target"] = "Aucune cible"
L["Out of combat and no target"] = "Hors combat et aucune cible"

L["Class Resource Text"] = "Texte des ressources de classe"
L["Click to select the value, then press Ctrl+C to copy it."] = "Cliquez pour sélectionner la valeur, puis appuyez sur Ctrl+C pour la copier."
L["HEX color"] = "Couleur HEX"
L["NSRT nickname integration"] = "Intégration des surnoms NSRT"
L["Nickname Integration"] = "Intégration des surnoms"
L["On (default): names supplied by Northern Sky Raid Tools replace character names on MSUF unit and group frames. Turn this off to always show character names in MSUF. NSRT and its settings are not modified."] = "Activé (par défaut) : les surnoms fournis par Northern Sky Raid Tools remplacent les noms de personnage sur les cadres d’unité et de groupe MSUF. Désactivez cette option pour toujours afficher les noms de personnage dans MSUF. NSRT et ses réglages ne sont pas modifiés."

-- Native 12.1 spell-ID tooltip CVar (Global > Misc > Unitframe tooltips).
L["Show spell IDs in aura tooltips"] = "Afficher les ID de sort dans les infobulles d'auras"
L["Aura tooltip spell IDs"] = "ID de sort dans les infobulles d'auras"
L["On: aura tooltips show the numeric spell ID through the game's own 12.1 option, and MSUF re-enables that option after every login because the game forgets it between sessions. Off (default): MSUF never touches the game option, so other addons or a manual console setting keep control; turning this switch off clears the option once."] = "Activé : les infobulles d'auras affichent l'ID numérique du sort via l'option native 12.1 du jeu, et MSUF réactive cette option après chaque connexion car le jeu l'oublie entre les sessions. Désactivé (par défaut) : MSUF ne touche jamais à l'option du jeu, afin que d'autres addons ou un réglage console manuel gardent le contrôle ; désactiver cet interrupteur coupe l'option une seule fois."

-- Guided setup restart confirmation.
L["Run the guided setup again? The walkthrough starts over at the first step."] = "Relancer la configuration guidée ? Le parcours reprend depuis la première étape."
L["Dispel Type Colors"] = "Couleurs des types de dissipation"
L["Magic custom"] = "Magie personnalisée"
L["Magic color"] = "Couleur de la magie"
L["Curse custom"] = "Malédiction personnalisée"
L["Curse color"] = "Couleur de la malédiction"
L["Disease custom"] = "Maladie personnalisée"
L["Disease color"] = "Couleur de la maladie"
L["Poison custom"] = "Poison personnalisé"
L["Poison color"] = "Couleur du poison"
L["Bleed custom"] = "Saignement personnalisé"
L["Bleed color"] = "Couleur du saignement"
L["Optional global overrides for harmful Magic, Curse, Disease, Poison and Bleed indicators. Off uses Blizzard's current default. The last edited type is shown first in every aura preview."] = "Couleurs globales facultatives pour les indicateurs néfastes de magie, malédiction, maladie, poison et saignement. Désactivé utilise la valeur actuelle de Blizzard. Le dernier type modifié apparaît en premier dans chaque aperçu d'aura."
L["Timer and Dispel colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "Les couleurs des minuteurs et dissipations sont partagées par les auras actives d'unité et de groupe et tous les aperçus. Les couleurs de bordure et d'ombre des icônes se trouvent dans Apparence > Auras, par type d'aura."
L["Cooldown timer urgency, global Dispel types, icon borders and shadows."] = "Urgence des minuteurs, types de dissipation globaux, bordures et ombres des icônes."
L["Safe, Warning, Urgent, Magic, Curse, Disease, Poison, Bleed, icon border and icon shadow."] = "Sûr, Avertissement, Urgent, Magie, Malédiction, Maladie, Poison, Saignement, bordure et ombre d'icône."
L["While unlocked, the Combat Enter/Leave text is shown permanently as a movable handle. Drag it with the mouse or nudge it with the arrow keys. Lock it so the text only appears when entering or leaving combat."] = "Tant que la position est déverrouillée, le texte d'entrée/sortie de combat reste affiché en permanence comme poignée déplaçable. Faites-la glisser avec la souris ou déplacez-la avec les touches fléchées. Verrouillez la position pour que le texte n'apparaisse qu'en entrant ou en sortant de combat."
L["While unlocked, the Combat Timer stays visible out of combat as a movable 0:00 placeholder. Drag it with the mouse or nudge it with the arrow keys - with click-through enabled, hold ALT to drag. Lock it to freeze the position."] = "Tant que la position est déverrouillée, le minuteur de combat reste visible hors combat sous forme d'espace réservé 0:00 déplaçable. Faites-le glisser avec la souris ou déplacez-le avec les touches fléchées – si le clic à travers est activé, maintenez ALT pour le faire glisser. Verrouillez la position pour la figer."
end
if type(MSUF.RegisterLocaleLoader) == "function" then MSUF.RegisterLocaleLoader("frFR", LoadLocale)
elseif MSUF.LOCALE == "frFR" then LoadLocale() end
